@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout.cshtml";
}
<section class="mx-auto max-w-3xl px-6 py-12">
    <h1 class="text-4xl font-bold tracking-tight text-slate-900">@Model.Heading</h1>

    @await Html.GetBlockGridHtmlAsync(Model, "body")

    <h2 class="mt-16 text-2xl font-semibold text-slate-900">Posts</h2>
    <ul class="mt-6 space-y-10">
        @foreach (var post in Model.Children<BlogPost>().OrderByDescending(p => p.PublishDate))
        {
            <li class="flex flex-col gap-4 sm:flex-row sm:gap-6">
                @if (post.ListingImage is not null)
                {
                    <img src="@post.ListingImage.GetCropUrl(width: 320, height: 200)" alt="" class="h-40 w-full flex-none rounded-lg object-cover sm:w-60" loading="lazy" />
                }
                <div>
                    <h3 class="text-xl font-semibold text-slate-900">
                        <a href="@post.Url()" class="hover:underline">@post.Title</a>
                    </h3>
                    <p class="text-sm text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</p>
                    <p class="mt-2 text-slate-700">@post.Excerpt</p>
                </div>
            </li>
        }
    </ul>
</section>

